messages.content:
Game edukasi daur ulang dengan tiga kategori sampah dan tema Cartoon, tempo Normal. Asumsi: rintangan memakai ukuran aman (batu dan genangan) agar selalu bisa dilompati.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "recycle-runner", title: "Recycle Runner", seed: "recycle-runner-01",
  theme: { preset: "cartoon" },

  learning: {
    subject: "Lingkungan Hidup",
    concept: "Membedakan bahan yang bisa dan tidak bisa didaur ulang",
    objectives: [
      "Mengelompokkan sampah berdasarkan sifat dan kemampuan daur ulangnya",
      "Mengenali plastik yang sulit didaur ulang"
    ],
    misconceptions: ["Semua jenis plastik bisa didaur ulang"],
    mode: "category",
    categories: [
      { id: "organik", label: "Organik", color: "#3FA34D" },
      { id: "daur-ulang", label: "Anorganik Daur Ulang", color: "#2F80ED" },
      { id: "sulit-daur-ulang", label: "Sulit Daur Ulang", color: "#E5484D" }
    ],
    items: [
      { id: "kulit-pisang", label: "Kulit pisang", category: "organik", explain: "Sampah alami yang cepat membusuk dan bisa dijadikan kompos." },
      { id: "daun-kering", label: "Daun kering", category: "organik", explain: "Bahan alami yang terurai menjadi kompos penyubur tanah." },
      { id: "sisa-nasi", label: "Sisa nasi", category: "organik", explain: "Sisa makanan yang mudah membusuk dan bisa dikomposkan." },
      { id: "botol-plastik", label: "Botol plastik", category: "daur-ulang", explain: "Plastik PET bernilai tinggi dan mudah didaur ulang jadi produk baru." },
      { id: "kaleng-minuman", label: "Kaleng minuman", category: "daur-ulang", explain: "Logam aluminium yang bisa didaur ulang berulang kali tanpa rusak." },
      { id: "kertas-koran", label: "Kertas koran", category: "daur-ulang", explain: "Serat kertas bersih bisa diolah kembali menjadi kertas daur ulang." },
      { id: "sedotan-plastik", label: "Sedotan plastik", category: "sulit-daur-ulang", explain: "Plastik kecil bercampur bahan lain, sulit diproses di fasilitas daur ulang." },
      { id: "styrofoam", label: "Styrofoam", category: "sulit-daur-ulang", explain: "Plastik berongga bernilai rendah, jarang diterima fasilitas daur ulang." },
      { id: "puntung-rokok", label: "Puntung rokok", category: "sulit-daur-ulang", explain: "Campuran serat dan bahan kimia yang tidak bisa didaur ulang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu", w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "genangan", w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```
